  field.value = 123;
} catch (error) {
  const e = error as { source?: string; code?: string };
  if (e.source === STORE_WASM_SOURCE && e.code === StoreWasmErrorCode.fieldDisposed) {
    // 字段已释放：新建字段而不是复用已释放实例
  } else {
    throw error;
  }
}

